text:
{
  "claims": [
    {
      "anchor": "By default the WAL is checkpointed once it reaches about 1000 pages",
      "claim_text": "By default, a checkpoint is run once the WAL reaches about 1000 pages.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P0.S0", "rel": "entails"},
        {"sid": "P4.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Both passages state the 1000-page default checkpoint threshold."
    },
    {
      "anchor": "which is roughly 4 MB",
      "claim_text": "A WAL of about 1000 pages is roughly 4 MB.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 4 states 1000 pages is about 4MB."
    },
    {
      "anchor": "the default page size implied by these numbers is about 8 KB",
      "claim_text": "The default page size implied by 1000 pages being about 4 MB is about 8 KB.",
      "kind": "arith",
      "sure": true,
      "evidence": [
        {"sid": "P4.S0", "rel": "entails"}
      ],
      "check": {"kind": "arith", "expr": "4 MB / 1000", "op": "==", "value": "8 KB"},
      "reasoning": "4MB divided by 1000 pages gives about 4KB, not 8KB."
    },
    {
      "anchor": "it can be changed at compile time with SQLITE_DEFAULT_WAL_AUTOCHECKPOINT",
      "claim_text": "The automatic checkpoint threshold can be changed at compile time with SQLITE_DEFAULT_WAL_AUTOCHECKPOINT.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P0.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 0 states this compile-time option specifies a different default."
    },
    {
      "anchor": "or at run time with the wal_autocheckpoint pragma",
      "claim_text": "The automatic checkpoint threshold can be changed at run time with the wal_autocheckpoint pragma.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P3.S3", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 3 states the threshold can be changed using wal_autocheckpoint pragma."
    },
    {
      "anchor": "The wal-index rarely exceeds 32 KiB",
      "claim_text": "The wal-index rarely exceeds 32 KiB in size.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P6.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 6 states the wal-index rarely exceeds 32 KiB."
    },
    {
      "anchor": "which is less than 1% of a full default-sized WAL",
      "claim_text": "32 KiB is less than 1% of a full default-sized WAL.",
      "kind": "arith",
      "sure": true,
      "evidence": [
        {"sid": "P6.S1", "rel": "entails"},
        {"sid": "P4.S0", "rel": "entails"}
      ],
      "check": {"kind": "arith", "expr": "32 KiB / 4 MB * 100", "op": "<", "value": "1"},
      "reasoning": "32KiB is about 0.78% of 4MB, so less than 1%."
    },
    {
      "anchor": "To get the best read performance you should checkpoint as rarely as possible",
      "claim_text": "To get the best read performance, one should checkpoint as rarely as possible.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P2.S1", "rel": "refutes"},
        {"sid": "P1.S2", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "Passages say frequent checkpoints maximize read performance, opposite of claim."
    },
    {
      "anchor": "let the WAL grow large",
      "claim_text": "To get the best read performance, one should let the WAL grow large.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P2.S1", "rel": "refutes"},
        {"sid": "P1.S2", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "Passages say keep WAL small for read performance."
    },
    {
      "anchor": "Normally the checkpoint does not truncate the WAL file unless journal_size_limit is set",
      "claim_text": "Normally the checkpoint does not truncate the WAL file unless the journal_size_limit pragma is set.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 4 states this exception."
    },
    {
      "anchor": "instead SQLite starts overwriting the file from the beginning",
      "claim_text": "Instead of truncating, the checkpoint causes SQLite to start overwriting the WAL file from the beginning.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 4 states this."
    },
    {
      "anchor": "because overwriting an existing file is normally faster than appending",
      "claim_text": "Overwriting an existing file is normally faster than appending.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S3", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 4 states this reason."
    }
  ]
}
